// Check if an array is a square array
private static boolean isSquareArray(int[] A) {
    // Loop through all adjacent pairs of elements in the array
    for (int i = 0; i < A.length - 1; i++) {
        // If the sum of the pair is not a perfect square, return false
        if (!isPerfectSquare(A[i] + A[i + 1])) {
            return false;
        }
    }

    // If all adjacent pairs are perfect squares, return true
    return true;
}

// Check if a number is a perfect square
private static boolean isPerfectSquare(int x) {
    // Check if x is a perfect square by checking if its square root is an integer
    return Math.sqrt(x) % 1 == 0;
}

// Generate all possible permutations of an array
private static List<int[]> permutations(int[] A) {
    // If the input array has only one element, return a list with one element
    if (A.length == 1) {
        return Arrays.asList(A);
    }

    // Initialize an empty list to store the permutations
    List<int[]> permutations = new ArrayList<>();

    // Loop through all possible positions of the first element in the permutation
    for (int i = 0; i < A.length; i++) {
        // Recursively generate the permutations for the rest of the array
        List<int[]> subPermutations = permutations(Arrays.copyOfRange(A, i + 1, A.length));

        // Add the first element to each permutation of the rest of the array
        for (int[] subPermutation : subPermutations) {
            int[] permutation = new int[A.length];
            permutation[i] = A[i];
            System.arraycopy(subPermutation, 0, permutation, i + 1, subPermutation.length);
            permutations.add(permutation);
        }
    }

    // Return the list of permutations
    return permutations;
}
