public static boolean isBoomerang(int[][] points) {
    // Check if the points are valid
    if (points.length != 3) {
        throw new IllegalArgumentException("Invalid number of points");
    }
    for (int[] point : points) {
        if (point.length != 2) {
            throw new IllegalArgumentException("Invalid point format");
        }
    }

    // Calculate the determinant of the matrix formed by the points
    int determinant = determinant(points);

    // Check if the determinant is equal to zero
    if (determinant == 0) {
        return false;
    }

    // Check if the points are in counterclockwise order
    int sum = 0;
    for (int i = 0; i < points.length; i++) {
        int[] point1 = points[i];
        int[] point2 = points[(i + 1) % points.length];
        sum += (point2[0] - point1[0]) * (point2[1] + point1[1]);
    }
    return sum < 0;
}

private static int determinant(int[][] matrix) {
    if (matrix.length != 2) {
        throw new IllegalArgumentException("Invalid matrix size");
    }
    return matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0];
}
